import'package:flutter/material.dart';import'../../core/network/api_client.dart';
class ReportsScreen extends StatefulWidget{const ReportsScreen({super.key,required this.api});final ApiClient api;@override State<ReportsScreen>createState()=>_State();}class _State extends State<ReportsScreen>{Map<String,dynamic>?report;String?error;@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await widget.api.dio.get<Map<String,dynamic>>('/api/v1/reports/sales');if(mounted)setState((){report=r.data;error=null;});}catch(_){if(mounted)setState(()=>error='Report la pa disponib pou wòl sa a.');}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('30-day Report')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(20),children:[if(error!=null)Text(error!),if(report!=null)...[_card('Sales','${report!['tickets']['sales']}'),_card('Tickets','${report!['tickets']['count']}'),_card('Payouts','${report!['payouts']['amount']}'),_card('Commission','${report!['commission']}')]])));Widget _card(String title,String value)=>Card(child:ListTile(title:Text(title),trailing:Text(value,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))));}
